fn merge(a: { ...r }, b: { ...s }): { ...r, ...s }
  where r disjoint s = { ...a, ...b };
fn merge3(a: { ...r }, b: { ...s }, c: { ...t }): { ...r, ...s, ...t }
  = merge(merge(a, b), c);
fn apply1(f: (a, b, c) -> { x: Int, y: Int, z: Int }, p: a): Int = 0;
fn main(): Int = apply1(merge3, { x: 1 });
